<?php
if(!defined('ABSPATH'))exit;
function bsktv_meta_box(){add_meta_box('bsktv_details','酒店資訊','bsktv_meta_render','post','normal','high');} add_action('add_meta_boxes','bsktv_meta_box');
function bsktv_meta_render($post){wp_nonce_field('bsktv_meta_save','bsktv_meta_nonce');$fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_phone'=>'電話','bsktv_line'=>'LINE／聯絡方式','bsktv_price'=>'消費區間','bsktv_model'=>'消費模式','bsktv_room'=>'包廂資訊','bsktv_head_price'=>'人頭費用','bsktv_room_price'=>'包廂費用','bsktv_table_price'=>'坐檯費用','bsktv_host_price'=>'少爺費用','bsktv_manager_price'=>'幹部費用','bsktv_base_price'=>'試算：基本費','bsktv_person_price'=>'試算：每人費用','bsktv_hour_price'=>'試算：每小時費用','bsktv_service_fee'=>'試算：服務費 %');echo '<div class="bsktv-admin-grid">';foreach($fields as $key=>$label){$v=get_post_meta($post->ID,$key,true);$type=(strpos($key,'price')!==false||$key==='bsktv_service_fee')?'number':'text';echo '<p><label><strong>'.esc_html($label).'</strong><br><input style="width:100%" type="'.esc_attr($type).'" min="0" step="0.01" name="'.esc_attr($key).'" value="'.esc_attr($v).'" /></label></p>';}echo '</div><p><strong>完整消費方案</strong><br><small>正式消費方案可直接使用文章編輯器的表格區塊呈現；以上費用欄位可供店家資訊卡與試算器使用。</small></p>';}
function bsktv_meta_save($id){if(!isset($_POST['bsktv_meta_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsktv_meta_nonce'])),'bsktv_meta_save'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;$text=array('bsktv_address','bsktv_hours','bsktv_phone','bsktv_line','bsktv_price','bsktv_model','bsktv_room');$numeric=array('bsktv_head_price','bsktv_room_price','bsktv_table_price','bsktv_host_price','bsktv_manager_price','bsktv_base_price','bsktv_person_price','bsktv_hour_price','bsktv_service_fee');foreach($text as $k){$v=isset($_POST[$k])?sanitize_text_field(wp_unslash($_POST[$k])):'';if($v==='')delete_post_meta($id,$k);else update_post_meta($id,$k,$v);}foreach($numeric as $k){$v=isset($_POST[$k])?floatval(wp_unslash($_POST[$k])):0;if($v<=0)delete_post_meta($id,$k);else update_post_meta($id,$k,$v);}} add_action('save_post_post','bsktv_meta_save');
function bsktv_meta($key,$id=null){return get_post_meta($id?:get_the_ID(),$key,true);}function bsktv_views($id=null){return (int)get_post_meta($id?:get_the_ID(),'bsktv_views',true);}function bsktv_is_featured($id=null){return get_post_meta($id?:get_the_ID(),'bsktv_featured',true)==='1';}function bsktv_is_home_featured($id=null){return get_post_meta($id?:get_the_ID(),'bsktv_home_featured',true)==='1';}
